<script setup>import {ref,computed} from 'vue';import AdminShell from '../../components/AdminShell.vue';import StatusPill from '../../components/StatusPill.vue';import {orders} from '../../api/mock';const active=ref('全部');const tabs=['全部','待调度','待提货','运输中','运输异常','已签收'];const filtered=computed(()=>active.value==='全部'?orders:orders.filter(o=>o.status===active.value));</script>
<template><AdminShell><template #title>运输订单</template><div class="action-row"><div class="filter-tabs"><button v-for="t in tabs" :key="t" :class="{active:active===t}" @click="active=t">{{t}} <small>{{t==='全部'?orders.length:orders.filter(o=>o.status===t).length}}</small></button></div><div><button class="secondary-btn">导出</button><button class="primary-btn">＋ 新建运输订单</button></div></div><section class="panel order-center"><div class="table-tools"><div class="search-box">⌕ <input placeholder="搜索运输单号、客户或目的地"/></div><button>提货日期：今日⌄</button><button>承运方式：全部⌄</button><button>更多筛选</button></div><table><thead><tr><th><input type="checkbox"/></th><th>运输单号</th><th>客户与货物</th><th>起讫地</th><th>计划时间</th><th>运力</th><th>运输进度</th><th>运费</th><th></th></tr></thead><tbody><tr v-for="o in filtered" :key="o.id"><td><input type="checkbox"/></td><td><b>{{o.no}}</b><div><StatusPill :status="o.status"/></div></td><td><b>{{o.customer}}</b><small>{{o.cargo}} · {{o.weight}}</small></td><td><div class="origin-dest"><span>{{o.origin}}</span><i></i><span>{{o.destination}}</span></div></td><td><small>提货 {{o.pickup}}</small><small>送达 {{o.delivery}}</small></td><td><b>{{o.plate}}</b><small>{{o.driver}}</small></td><td><div class="progress-line"><i :style="{width:o.progress+'%'}"></i></div><small>{{o.progress}}% · {{o.eta}}</small></td><td><b>{{o.freight}}</b></td><td><button class="more-btn">•••</button></td></tr></tbody></table><div class="pagination"><span>共 {{filtered.length}} 条记录</span><div><button>‹</button><button class="active">1</button><button>2</button><button>›</button></div></div></section></AdminShell></template>
